这样单核上的数据（ 2048个数）被切分成 16块，每块 tileLength （128）个数据。
TPipe为inQueueX 分配了两块大小为 tileLength * sizeof(float) 个字节的内存块，每个
内存块能容纳 tileLength （128）个float类型数据。数据切分示意图如下。
图1-4 单核数据切分示意图
具体的初始化函数代码如下：
// Kernel 侧所需头文件
#include "kernel_operator.h"
constexpr int32_t BUFFER_NUM = 2;                                     // tensor num for each queue
__aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, uint32_t totalLength, uint32_t tileNum)
{

     this->blockLength = totalLength / AscendC::GetBlockNum();     // length computed of each core
     this->tileNum = tileNum;                                      // split data into 8 tiles for each core
     this->tileLength = this->blockLength / tileNum / BUFFER_NUM;  // separate to 2 parts, due to double 
buffer
     // get start index for current core, core parallel
     xGm.SetGlobalBuffer((__gm__  float *)x + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
     yGm.SetGlobalBuffer((__gm__  float *)y + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
     zGm.SetGlobalBuffer((__gm__  float *)z + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
     // pipe alloc memory to queue, the unit is Bytes
     pipe.InitBuffer(inQueueX,  BUFFER_NUM, this->tileLength * sizeof(float));
     pipe.InitBuffer(inQueueY,  BUFFER_NUM, this->tileLength * sizeof(float));
     pipe.InitBuffer(outQueueZ,  BUFFER_NUM, this->tileLength * sizeof(float));
}
步骤5基于矢量编程范式，将核函数的实现分为 3个基本任务： CopyIn，Compute ，
CopyOut 。Process函数中通过如下方式调用这三个函数。
__aicore__ inline void Process()
{
    // loop count need to be doubled, due to double buffer
    int32_t loopCount = this->tileNum * BUFFER_NUM;
    // tiling strategy, pipeline parallel
    for (int32_t i = 0; i < loopCount; i++) {
        CopyIn(i);
        Compute(i);
        CopyOut(i);
    }
}
1. CopyIn 函数实现。
a.使用6.2.3.1.1 DataCopy 接口将 GlobalTensor 数据拷贝到 LocalTensor 。
b.使用 EnQue将LocalTensor 放入VecIn的Queue中。
__aicore__ inline void CopyIn( int32_t progress)
{
    // alloc tensor from queue memoryCANN社区版
Ascend C 算子开发 1 入门教程
文档版本  01 (2026-05-21) 版权所有  © 华为技术有限公司 11

    AscendC::LocalTensor<float>  xLocal = inQueueX.AllocTensor<float>();
    AscendC::LocalTensor<float>  yLocal = inQueueY.AllocTensor<float>();
    // copy progress_th tile from global tensor to local tensor
    AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], this->tileLength);
    AscendC::DataCopy(yLocal, yGm[progress * this->tileLength], this->tileLength);
    // enque input tensors to VECIN queue
    inQueueX.EnQue(xLocal);
    inQueueY.EnQue(yLocal);
}
2. Compute 函数实现。
a.使用 DeQue从VecIn中取出 LocalTensor 。
b.使用Ascend C 接口 Add完成矢量计算。
c.使用 EnQue将计算结果 LocalTensor 放入到 VecOut的Queue中。
d.使用 FreeTensor 将释放不再使用的 LocalTensor 。
__aicore__ inline void Compute(int32_t progress)
{
    // deque input tensors from VECIN queue
    AscendC::LocalTensor<float>  xLocal = inQueueX.DeQue<float>();
    AscendC::LocalTensor<float>  yLocal = inQueueY.DeQue<float>();
    AscendC::LocalTensor<float>  zLocal = outQueueZ.AllocTensor<float>();
    // call Add instr for computation
    AscendC::Add(zLocal, xLocal, yLocal, this->tileLength);
    // enque the output tensor to VECOUT queue
    outQueueZ.EnQue<float>(zLocal);
    // free input tensors for reuse
    inQueueX.FreeTensor(xLocal);
    inQueueY.FreeTensor(yLocal);
}
3. CopyOut 函数实现。
a.使用 DeQue接口从 VecOut的Queue中取出 LocalTensor 。
b.使用6.2.3.1.1 DataCopy 接口将 LocalTensor 拷贝到 GlobalTensor 上。
c.使用 FreeTensor 将不再使用的 LocalTensor 进行回收。
 __aicore__ inline void CopyOut(int32_t progress)
{
    // deque output tensor from VECOUT queue
    AscendC::LocalTensor<float>  zLocal = outQueueZ.DeQue<float>();
    // copy progress_th tile from local tensor to global tensor
    AscendC::DataCopy(zGm[progress * this->tileLength], zLocal, this->tileLength);
    // free output tensor for reuse
    outQueueZ.FreeTensor(zLocal);
}
----结束
