然后完成算子 host实现cpp文件中 Tiling函数实现，该文件命名为 “算子名称 .cpp”，
位于算子工程的 op_host目录下。 Tiling函数的原型是固定的，接受一个 TilingContext
作为输入，在此 context上可以获取到输入、输出的 Shape指针等内容。注册的 Tiling函
数由框架调用，调用时会传入 TilingContext 参数。样例代码如下：
namespace optiling {
const uint32_t NUM_BLOCKS = 8;
const uint32_t TILE_NUM = 8;
static ge::graphStatus TilingFunc(gert::TilingContext *context)
{
    TilingData tiling;
    uint32_t totalLength = context->GetInputShape(0)->GetOriginShape().GetShapeSize();
    context->SetBlockDim(NUM_BLOCKS);
    tiling.set_totalLength(totalLength);
    tiling.set_tileNum(TILE_NUM);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),  context->GetRawTilingData()-
>GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;CANN社区版
