template<typename T>
ge::graphStatus ReshapeInferShapeImpl(const T *reshape_dims, const gert::Shape &x_shape, gert::Shape 
&output_shape, int32_t reshape_rank) {
    constexpr T UNKNOWN_DIM = -1;CANN社区版
