#include "../../op_kernel/add_custom_tiling_sink/add_custom_tiling_sink_tiling_struct.h"
#include "add_custom_tiling_sink_tiling.h"
#include "register/device_op_impl_registry.h"
#include "tiling/platform/platform_ascendc.h"
namespace optiling {
static constexpr uint32_t NUM_BLOCKS = 8;
static constexpr uint32_t TILE_NUM = 3;
static constexpr size_t MAX_WORKSPACE_SIZE = 32; // 算子所需用户 workspace 空间最大值，
AddCustomTilingSink 算子本身逻辑无需用户 workspace 空间，此处设置为固定值仅作为示例
static constexpr size_t DEFAULT_WORKSPACE_SIZE = 0;
ge::graphStatus AddCustomSinkTilingFunc(gert::TilingContext *context)
{
    TilingSinkTilingData *tiling = context->GetTilingData<TilingSinkTilingData>();
    uint32_t totalLength = context->GetInputTensor(0)->GetShapeSize();
    context->SetBlockDim(NUM_BLOCKS);
    tiling->totalLength = totalLength;
    tiling->tileNum = TILE_NUM;
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    auto platform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
    size_t sysWorkspaceSize = platform.GetLibApiWorkSpaceSize();
    currentWorkspace[0] = sysWorkspaceSize + DEFAULT_WORKSPACE_SIZE; // 设置运行时 workspace 大
小，此处为系统 workspace 空间 + 用户workspace 空间
    if (context->GetInputTensor(1) != nullptr && context->GetInputTensor(1)->GetData<float>()  == 
nullptr) {
        // 通过判断值依赖 InputTensor 的Data是否为空指针来确认当前是否处于编译期。
        // Tiling 下沉场景，编译期需要为算子分配内存，包括其所需的 workspace 。为了保证运行时的高效
性，编译期应根据算子的执行需求，合理设置所需的 workspace 最大值，以避免内存不足或浪费。
        currentWorkspace[0] = sysWorkspaceSize + MAX_WORKSPACE_SIZE; // 设置编译期 workspace 大
小，此处为系统 workspace 空间 + 用户workspace 空间最大值
    }
    return ge::GRAPH_SUCCESS;
}
DEVICE_IMPL_OP_OPTILING(AddCustomTilingSink).Tiling(optiling::AddCustomSinkTilingFunc); // 下沉
tiling函数注册
} // namespace optiling
