namespace ascendc_ops {
at::Tensor ascendc_add(const at::Tensor& x, const at::Tensor& y)
{
    // 运行资源申请，通过 c10_npu::getCurrentNPUStream() 的函数获取当前 NPU上的流
    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);
    // 分配Device侧输出内存
    at::Tensor z = at::empty_like(x);
    uint32_t numBlocks = 8;
    uint32_t totalLength = 1;
    for (uint32_t size : x.sizes()) {
        totalLength *= size;
    }
    // 用<<<>>>接口调用核函数完成指定的运算
    add_custom<<<numBlocks, nullptr, aclStream>>>((uint8_t*)(x.mutable_data_ptr()), (uint8_t*)
(y.mutable_data_ptr()), (uint8_t*)(z.mutable_data_ptr()), totalLength);
    // 将Device上的运算结果拷贝回 Host并释放申请的资源
    return z;
}
} // namespace ascendc_ops
