步骤1Stage1：CopyIn函数实现。
1.使用DataCopy 接口将 GlobalTensor 数据拷贝到 LocalTensor 。
2.使用EnQue将LocalTensor 放入VECIN的Queue中。
__aicore__ inline void CopyIn()
{
    // 从Que中为LocalTensor 分配内存
    AscendC::LocalTensor<half> xLocal = inQueueX.AllocTensor<half>();
    AscendC::LocalTensor<half> yLocal = inQueueY.AllocTensor<half>();
    // 将GlobalTensor 数据拷贝到 LocalTensor
    AscendC::DataCopy(xLocal, xGm, TOTAL_LENGTH);
    AscendC::DataCopy(yLocal, yGm, TOTAL_LENGTH);
    // LocalTensor 放入VECIN的Queue中
    inQueueX.EnQue(xLocal);
    inQueueY.EnQue(yLocal);
}
