kernel侧实现的代码框架如下，在完成 Matmul对象的初始化、左矩阵 A、右矩阵 B、
Bias的设置后，通过单次 Iterate叠加while循环的方式完成后续的 Matmul计算、
LeakyRelu 计算、 CopyOut 流程。
template<typename aType, typename bType, typename cType, typename biasType>
__aicore__ inline void MatmulLeakyKernel<aType, bType, cType, biasType>::Process(){
    uint32_t computeRound = 0;

    // 设置Matmul的输入（包括左矩阵、右矩阵、 bias）
    matmulObj.SetTensorA(aGlobal);
    matmulObj.SetTensorB(bGlobal);
    matmulObj.SetBias(biasGlobal);
    // 调用matmul iterate 获取一块 [baseM, baseN] 的计算结果
    while (matmulObj.template Iterate<true>())
    {
        MatmulCompute();
        LeakyReluCompute();
        CopyOut(computeRound);
        computeRound++;
    }
    matmulObj.End();
}
