循环内成员变量访问优化
在一个 VF内，不推荐直接访问类的成员变量。直接访问类的成员变量相当于从栈上把
内容搬运到 Tensor寄存器中，之后通过地址访问 Tensor上的内容，该操作将导致 VF融
合失效，建议通过局部变量临时传参解决，示例如下：
//【反例】直接读取成员变量
__aicore__ inline void SoftMaxGenericNDImpVF(__ubuf__ float*  dstAddr, __ubuf__ float*  sumAddr, __ubuf__ 
float*  maxAddr,
    __ubuf__ float*  srcAddr, __ubuf__ float*  workAddr, const LastAxisShapeND originalSrcShape, const 
SoftMaxTiling tiling)
{
    for (uint16_t i = 0; i < (uint16_t)tiling.srcM; i++) {
        AscendC::ReduceMax(maxAddr + i * FLOAT_NUM_PER_BLK, srcAddr + i * tiling.srcK, workAddr, 
(uint16_t)originalSrcShape.k);
    }
}
//【正例】通过局部变量传递 VF内访问的成员变量
__aicore__ inline void SoftMaxGenericNDImpVF(__ubuf__ float*  dstAddr, __ubuf__ float*  sumAddr, __ubuf__ 
float*  maxAddr,
    __ubuf__ float*  srcAddr, __ubuf__ float*  workAddr, const LastAxisShapeND originalSrcShape, const 
SoftMaxTiling tiling)
{
    uint16_t srcK = tiling.srcK;
    uint16_t srcM = tiling.srcM;
    uint16_t reduceK = FLOAT_NUM_PER_BLK;
    uint16_t originK = (uint16_t)originalSrcShape.k;
    for (uint16_t i = 0; i < (uint16_t)srcM; i++) {
        AscendC::ReduceMax(maxAddr + i * reduceK, srcAddr + i * srcK, workAddr, originK);
    }
}
循环内指令分布优化
减少Loop循环内非索引相关语句。 for循环中存在与索引无关的语句可以提出 for循环外
来减少指令数。
//【反例】 Duplicate 语句放在 for循环中，每次循环都会执行一次
template<typename T>
__simd_vf__ inline void DuplicateVF(__ubuf__ T* dstAddr, T scalarValue, uint32_t oneRepeatSize, uint16_t 
repeatTimes)
{
    AscendC::Reg::RegTensor<T> dstReg;
    AscendC::Reg::MaskReg mask = AscendC::Reg::CreateMask<T>();  
    for (uint16_t i = 0; i < repeatTimes; i++) {
        AscendC::Reg::Duplicate(dstReg, scalarValue);
        AscendC::Reg::StoreAlign(dstAddr + i * oneRepeatSize, dstReg, mask);
    }
}
